const item = $input.first().json;
const chave = Object.keys(item)[0];
const texto = item[chave];

const linhas = texto.trim().split('\n').map(l => l.trim());
const cabecalhos = linhas[0].split(',');

return linhas.slice(1).map(linha => {
  const valores = linha.split(',');
  const novoItem = {};
  cabecalhos.forEach((h, i) => novoItem[h] = valores[i]);
  return { json: novoItem };
});

// Opções de investimento (vindas do nó anterior, já parseadas do CSV)
const opcoes = $input.all().map(i => i.json);

// Clientes vindos do Webhook (payload enviado pelo notebook Python)
const dadosWebhook = $('Webhook').first().json;
const clientes = dadosWebhook.body || dadosWebhook;

const templates = {
  'Conservador': 'Prezado(a) {nome}, para o seu perfil Conservador recomendamos foco em renda fixa e segurança.',
  'Moderado': 'Prezado(a) {nome}, para o seu perfil Moderado recomendamos um mix equilibrado entre renda fixa e variável.',
  'Arrojado': 'Prezado(a) {nome}, para o seu perfil Arrojado recomendamos ênfase em ações e maior potencial de retorno.'
};

return clientes.map(cliente => {
  const perfil = cliente.perfil;
  const opcoesDoPerfil = opcoes.filter(o => o.perfil === perfil);
  const listaOpcoes = opcoesDoPerfil
    .map(o => `- ${o.produto} (mínimo R$${o.minimo}, rentabilidade ${o.rentabilidade})`)
    .join('\n');

  const template = templates[perfil] || 'Perfil não reconhecido.';
  const mensagem = template.replace('{nome}', cliente.nome) +
    '\n\nOpções recomendadas:\n' + listaOpcoes;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: perfil,
      mensagem: mensagem
    }
  };
});
